"use strict";(()=>{const PLACES=window.LEARNWITHUS_INDIA_PLACES||[],selector=document.getElementById('stateSelector'),fact=document.getElementById('indiaFact'),challenge=document.getElementById('mapChallenge'),prompt=document.getElementById('mapGamePrompt'),answerArea=document.getElementById('mapAnswerArea'),next=document.getElementById('mapNextChallenge'),modeLabel=document.getElementById('mapChallengeMode'),marker=document.getElementById('mapTargetMarker');if(!selector||!fact)return;const speak=text=>{if(!('speechSynthesis'in window))return;speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='en-IN';u.rate=.76;speechSynthesis.speak(u)},esc=s=>String(s).replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c])),shuffle=a=>[...a].sort(()=>Math.random()-.5);let mode=null,target=null;function showPlace(p){document.querySelectorAll('.state-choice').forEach(el=>{const active=el.dataset.name===p.name;el.classList.toggle('active',active);el.setAttribute('aria-pressed',active?'true':'false')});fact.innerHTML='<div class="india-fact-kicker">'+(p.type==='State'?'⭐ State':'📍 Union Territory')+'</div><h3>'+esc(p.name)+'</h3><dl><dt>Capital</dt><dd>'+esc(p.capital)+'</dd><dt>Region</dt><dd>'+esc(p.region)+'</dd><dt>Major language</dt><dd>'+esc(p.language)+'</dd></dl><p class="india-fact-note">Choose another place below the map to keep exploring.</p>';window.LearnWithUs?.recordComplete('india.html')}function buildGroup(title,items){const g=document.createElement('section');g.className='state-choice-group';g.innerHTML='<h4>'+title+' ('+items.length+')</h4>';const row=document.createElement('div');row.className='state-choice-grid';items.slice().sort((a,b)=>a.name.localeCompare(b.name)).forEach(p=>{const b=document.createElement('button');b.type='button';b.className='state-choice';b.dataset.name=p.name;b.textContent=p.name;b.setAttribute('aria-pressed','false');b.onclick=()=>showPlace(p);row.append(b)});g.append(row);selector.append(g)}buildGroup('States',PLACES.filter(p=>p.type==='State'));buildGroup('Union territories',PLACES.filter(p=>p.type==='Union Territory'));function optionsFor(field,correct){const vals=[...new Set(PLACES.map(p=>p[field]).filter(v=>v!==correct))];return shuffle([correct,...shuffle(vals).slice(0,4)])}function sayResult(ok,answer){const msg=ok?'Correct answer!':'Wrong answer. The correct answer is '+answer+'.';prompt.textContent=msg;prompt.classList.toggle('correct',ok);prompt.classList.toggle('wrong',!ok);speak(msg);answerArea.querySelectorAll('button,input').forEach(x=>x.disabled=true);next.hidden=false;next.focus()}function startChallenge(){challenge.hidden=false;next.hidden=true;answerArea.replaceChildren();prompt.classList.remove('correct','wrong');target=PLACES[Math.floor(Math.random()*PLACES.length)];if(marker){marker.hidden=true;marker.style.left='';marker.style.top=''}if(mode==='find'){modeLabel.textContent='📍 Map Hunt · type the place name';prompt.textContent='Look at the marker on the map. Which state or union territory is it?';if(marker){marker.hidden=false;marker.style.left=target.x+'%';marker.style.top=target.y+'%'}const wrap=document.createElement('div');wrap.className='map-text-answer';wrap.innerHTML='<label for="mapTextInput">Your answer</label><input id="mapTextInput" class="spelling-input" autocomplete="off" placeholder="Type the state or UT"><button id="checkMapText" class="practice-button" type="button">Check answer</button>';answerArea.append(wrap);document.getElementById('checkMapText').onclick=()=>{const value=document.getElementById('mapTextInput').value.trim().toLowerCase(),ok=value===target.name.toLowerCase();sayResult(ok,target.name)}}else{const field=mode==='capital'?'capital':'region',correct=target[field];modeLabel.textContent=mode==='capital'?'🏛️ Capital Match · choose one of five':'🧭 Region Match · choose one of five';prompt.textContent=mode==='capital'?'What is the capital of '+target.name+'?':'Which region is '+target.name+' in?';const row=document.createElement('div');row.className='game-options map-five-options';optionsFor(field,correct).forEach(v=>{const b=document.createElement('button');b.type='button';b.textContent=v;b.onclick=()=>sayResult(v===correct,correct);row.append(b)});answerArea.append(row)}challenge.scrollIntoView({behavior:'smooth',block:'nearest'})}document.querySelectorAll('[data-map-game]').forEach(b=>b.onclick=()=>{mode=b.dataset.mapGame;startChallenge()});if(next)next.onclick=startChallenge;})();